    const uint8_t *data = (const uint8_t *)key;
    uint32_t h1 = seed;
    uint32_t h2 = seed;

    for (size_t i = 0; i < len; i++) {
        h1 = h1 * 31 + data[i];
        h2 = h2 * 37 + data[i];
